rep("let page='home', searchTerm='',filter='All';","let page='home', searchTerm='',filter='All';\nconst photoUrls={};\nfunction dbOpen(){return new Promise((resolve,reject)=>{const r=indexedDB.open('everyday-dashboard-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('photos');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}\nasync function photoPut(key,blob){const db=await dbOpen();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').put(blob,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}\nasync function photoGet(key){try{const db=await dbOpen();return await new Promise((resolve,reject)=>{const r=db.transaction('photos').objectStore('photos').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}catch{return null}}\nasync function photoDelete(key){try{const db=await dbOpen();db.transaction('photos','readwrite').objectStore('photos').delete(key)}catch{}}\nasync function hydratePhotos(){for(const item of state.wardrobe){if(!item.photoKey)continue;const img=document.getElementById('photo-'+item.id);if(!img)continue;let blob=await photoGet(item.photoKey);if(blob){if(photoUrls[item.photoKey])URL.revokeObjectURL(photoUrls[item.photoKey]);photoUrls[item.photoKey]=URL.createObjectURL(blob);img.src=photoUrls[item.photoKey];img.hidden=false;const ph=document.getElementById('placeholder-'+item.id);if(ph)ph.hidden=true}}}", 'photo db functions')
