old="function wardrobeView(){let cats=[...new Set(state.wardrobe.map(x=>x.Category).filter(Boolean))].sort();let arr=filtered(state.wardrobe,['Category']);let rows=arr.map(x=>`<tr><td class=\"rowname\">${esc(x.Name)}</td><td>${esc(x.Category)}</td><td>${esc(x['Colour / Details'])}</td><td><span class=\"pill\">${esc(x['Wash Category'])}</span></td><td><select onchange=\"updateItem('wardrobe','${x.id}','Laundry Status',this.value)\">${['In Wardrobe','Clean','In Wash','To Put Away','Worn'].map(s=>`<option ${x['Laundry Status']===s?'selected':''}>${esc(x['Laundry Status']===s?s:s)}</option>`).join('')}${!['In Wardrobe','Clean','In Wash','To Put Away','Worn'].includes(x['Laundry Status'])?`<option selected>${esc(x['Laundry Status'])}</option>`:''}</select></td><td><button class=\"smallbtn\" onclick=\"removeItem('wardrobe','${x.id}')\">×</button></td></tr>`).join('');return `<div class=\"sectionintro\"><p>${state.wardrobe.length} items imported from your wardrobe spreadsheet. Change the laundry status as you wear and wash things.</p></div>${toolbar(cats,\"openForm('wardrobe')\",'Search clothes, colour, category')} ${table(['Item','Category','Colour / details','Wash group','Laundry status',''],rows)}`}"
new="""function wardrobeView(){let cats=[...new Set(state.wardrobe.map(x=>x.Category).filter(Boolean))].sort();let arr=filtered(state.wardrobe,['Category']);let cards=arr.map(x=>`<article class=\"garment ${state.selectedOutfit.includes(x.id)?'selected':''}\"><div class=\"garment-photo\"><img id=\"photo-${x.id}\" alt=\"Photo of ${esc(x.Name)}\" hidden><span class=\"photo-placeholder\" id=\"placeholder-${x.id}\">${garmentEmoji(x.Category)}</span><button class=\"favorite ${x.favorite?'on':''}\" title=\"Favourite\" onclick=\"toggleFavorite('${x.id}')\">${x.favorite?'♥':'♡'}</button><button class=\"photo-btn\" onclick=\"document.getElementById('upload-${x.id}').click()\">＋ Add photo</button><input id=\"upload-${x.id}\" type=\"file\" accept=\"image/*\" hidden onchange=\"uploadClothingPhoto('${x.id}',this)\"></div><div class=\"garment-body\"><div class=\"garment-title\">${esc(x.Name)}</div><div class=\"garment-meta\">${esc(x.Category)} · ${esc(x['Colour / Details'])}</div><div class=\"garment-actions\"><select onchange=\"updateItem('wardrobe','${x.id}','Laundry Status',this.value)\">${['In Wardrobe','Clean','In Wash','To Put Away','Worn'].map(s=>`<option ${x['Laundry Status']===s?'selected':''}>${s}</option>`).join('')}${!['In Wardrobe','Clean','In Wash','To Put Away','Worn'].includes(x['Laundry Status'])?`<option selected>${esc(x['Laundry Status'])}</option>`:''}</select><button class=\"pick-btn ${state.selectedOutfit.includes(x.id)?'on':''}\" onclick=\"toggleOutfitItem('${x.id}')\">${state.selectedOutfit.includes(x.id)?'✓ Added':'＋ Outfit'}</button></div></div></article>`).join('');return `<div class=\"sectionintro\"><p>${state.wardrobe.length} pieces, ready to browse. Add a photo to make this your visual closet, then tap <b>＋ Outfit</b> to style a look.</p></div>${toolbar(cats,\"openForm('wardrobe')\",'Search clothes, colour, category')}<div class=\"gallery\">${cards||'<div class=\"empty\">No clothing matches this search.</div>'}</div>`}
function garmentEmoji(cat){let c=(cat||'').toLowerCase();return /shoe|footwear|trainers/.test(c)?'👟':/trouser|jean|short|bottom/.test(c)?'👖':/coat|jacket|hoodie|sweater|knit/.test(c)?'🧥':/bag/.test(c)?'👜':/accessor/.test(c)?'🧢':'👕'}
function toggleFavorite(id){let x=state.wardrobe.find(x=>x.id===id);if(x)x.favorite=!x.favorite;save();render()}
function toggleOutfitItem(id){let set=new Set(state.selectedOutfit);if(set.has(id))set.delete(id);else set.add(id);state.selectedOutfit=[...set];save();render()}
async function uploadClothingPhoto(id,input){let file=input.files&&input.files[0];if(!file)return;try{let img=await new Promise((resolve,reject)=>{let i=new Image(),u=URL.createObjectURL(file);i.onload=()=>{URL.revokeObjectURL(u);resolve(i)};i.onerror=reject;i.src=u});let scale=Math.min(1,900/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.78));let key='clothing-'+id;await photoPut(key,blob);let item=state.wardrobe.find(x=>x.id===id);if(item)item.photoKey=key;save();render();toast('Photo added to your closet')}catch(e){alert('Could not save this photo. Try choosing a smaller image.')}input.value=''}
function outfitsView(){let selected=state.wardrobe.filter(x=>state.selectedOutfit.includes(x.id));let available=filtered(state.wardrobe,['Category']);let pieces=selected.map(x=>`<div class=\"outfit-piece\"><img id=\"railphoto-${x.id}\" alt=\"\" hidden><span class=\"outfit-thumb\" id=\"railplaceholder-${x.id}\">${garmentEmoji(x.Category)}</span><div><div class=\"outfit-name\">${esc(x.Name)}</div><div class=\"outfit-sub\">${esc(x.Category)}</div></div><button class=\"smallbtn\" onclick=\"toggleOutfitItem('${x.id}')\">×</button></div>`).join('');let opts=[...new Set(state.wardrobe.map(x=>x.Category).filter(Boolean))].sort();let list=available.map(x=>`<label class=\"checkline\"><input type=\"checkbox\" ${state.selectedOutfit.includes(x.id)?'checked':''} onchange=\"toggleOutfitItem('${x.id}')\"><span style=\"flex:1\"><b>${esc(x.Name)}</b><div class=\"muted\">${esc(x.Category)} · ${esc(x['Laundry Status'])}</div></span></label>`).join('');let saved=state.outfits.map(o=>{let its=state.wardrobe.filter(x=>o.items.includes(x.id));return `<article class=\"saved-look\"><h3>${esc(o.name)}</h3><div class=\"saved-thumbs\">${its.slice(0,5).map(x=>x.photoKey?`<img data-photo-key=\"${esc(x.photoKey)}\" alt=\"\">`:`<span>${garmentEmoji(x.Category)}</span>`).join('')}</div><div class=\"muted\" style=\"font-size:11px;margin-bottom:10px\">${its.length} pieces${o.note?' · '+esc(o.note):''}</div><div class=\"look-actions\"><button class=\"btn soft\" onclick=\"loadOutfit('${o.id}')\">Edit look</button><button class=\"btn\" onclick=\"wearOutfit('${o.id}')\">Wear this</button><button class=\"smallbtn\" onclick=\"deleteOutfit('${o.id}')\">×</button></div></article>`}).join('');return `<div class=\"sectionintro\"><p>Choose clothes from your closet to compose a look. Save favourite combinations and bring them back whenever you like.</p></div><div class=\"outfit-layout\"><section class=\"card\"><div class=\"cardhead\"><div><h2>Choose your pieces</h2><span class=\"muted\" style=\"font-size:12px\">${state.selectedOutfit.length} selected</span></div><button class=\"smallbtn\" onclick=\"clearOutfit()\">Clear selection</button></div><div class=\"toolbar\"><input class=\"field search\" placeholder=\"Find a piece\" value=\"${esc(searchTerm)}\" oninput=\"searchTerm=this.value;render()\"><select onchange=\"filter=this.value;render()\"><option>All</option>${opts.map(c=>`<option ${filter===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div style=\"max-height:520px;overflow:auto;padding-right:5px\">${list}</div></section><aside class=\"card outfit-rail\"><div class=\"cardhead\"><div><div class=\"eyebrow\">THE LOOK</div><h2>Outfit in progress</h2></div><span class=\"pill green\">${selected.length} pieces</span></div>${pieces?`<div class=\"outfit-items\">${pieces}</div>`:'<div class=\"empty\">Your canvas is waiting. Choose pieces to get started.</div>'}<button class=\"btn primary\" style=\"width:100%\" onclick=\"saveOutfit()\" ${selected.length?'':'disabled'}>✦ Save this outfit</button><button class=\"btn\" style=\"width:100%;margin-top:8px\" onclick=\"wearSelection()\" ${selected.length?'':'disabled'}>Wear these pieces</button></aside></div><div class=\"card\" style=\"margin-top:18px\"><div class=\"cardhead\"><h2>Saved outfits</h2><span class=\"pill\">${state.outfits.length} looks</span></div>${saved?`<div class=\"saved-grid\">${saved}</div>`:'<div class=\"heart-empty\">Saved looks will live here, ready for a repeat.</div>'}</div>`}
function clearOutfit(){state.selectedOutfit=[];searchTerm='';filter='All';save();render()}
function saveOutfit(){if(!state.selectedOutfit.length)return;let name=prompt('Give this outfit a name','Everyday look');if(name===null)return;name=name.trim()||'Untitled outfit';state.outfits.unshift({id:'o'+Date.now(),name,items:[...state.selectedOutfit],note:''});save();toast('Outfit saved');render()}
function loadOutfit(id){let o=state.outfits.find(x=>x.id===id);if(o){state.selectedOutfit=[...o.items];page='outfits';searchTerm='';filter='All';save();render();window.scrollTo({top:0,behavior:'smooth'})}}
function deleteOutfit(id){state.outfits=state.outfits.filter(x=>x.id!==id);save();render()}
function wearSelection(){let ids=new Set(state.selectedOutfit);state.wardrobe.forEach(x=>{if(ids.has(x.id))x['Laundry Status']='Worn'});save();toast('Marked as worn');render()}
function wearOutfit(id){let o=state.outfits.find(x=>x.id===id);if(!o)return;let ids=new Set(o.items);state.wardrobe.forEach(x=>{if(ids.has(x.id))x['Laundry Status']='Worn'});save();toast('Outfit marked as worn');render()}
function toast(text){let el=document.getElementById('toast');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}"""
