rep("function restoreBackup(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let d=JSON.parse(r.result);if(!d.wardrobe||!d.grooming)throw 0;state={...initial,...d};save();render();alert('Backup imported.')}catch{alert('That file is not a valid dashboard backup.')}};r.readAsText(f);e.target.value=''}", "function restoreBackup(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=async()=>{try{let d=JSON.parse(r.result);if(!d.wardrobe||!d.grooming)throw 0;const photos=d.photos||{};delete d.photos;state={...initial,...d};for(const [key,url] of Object.entries(photos)){const blob=await (await fetch(url)).blob();await photoPut(key,blob)}save();render();alert('Backup imported.')}catch{alert('That file is not a valid dashboard backup.')}};r.readAsText(f);e.target.value=''}",'backup import')
